<script setup lang="ts">
import PaymentReceipt from './PaymentReceipt.vue';
import DailyCollections from './DailyCollections.vue';
import PonCollections from './PonCollections.vue';
import FinanceCharts from './FinanceCharts.vue';
import { computed, defineAsyncComponent, onMounted, ref, watch } from 'vue';
import { useRouter } from 'vue-router';
import { useInvoicesStore } from '@/stores/invoices';
import { useAuthStore } from '@/stores/auth';
import { supabase } from '@/lib/supabase';
import { apiFetch } from '@/lib/api';
import { formatPen, penCents, penDecimal, limaDate } from '@/lib/financeMoney';
import type { Invoice } from '@/types/domain';

const FinanceReconciliation=defineAsyncComponent(()=>import('./FinanceReconciliation.vue'));
const router=useRouter(), store=useInvoicesStore(), auth=useAuthStore();
const tabs=['Resumen financiero','Facturas','Cobranzas','Morosidad','Descuentos','Reportes','Auditoría'];
const receiptView=ref<InstanceType<typeof PaymentReceipt>|null>(null),dailyView=ref<InstanceType<typeof DailyCollections>|null>(null);
const collectionsView=ref('pon'),ponCollections=ref<InstanceType<typeof PonCollections>|null>(null);
const tab=ref(0),page=ref(1),from=ref(limaDate().slice(0,7)+'-01'),to=ref(limaDate()),mode=ref('month'),year=ref(limaDate().slice(0,4)),month=ref(limaDate().slice(5,7));
const search=ref(''),state=ref(''),zone=ref(''),contractId=ref(''),grouped=ref(false),loading=ref(false),error=ref(''),notice=ref('');
const zones=ref<{id:string;name:string}[]>([]);
interface Summary { openingBalance?:string; series?:{month:string;billed:string;received:string}[]; zones?:{name:string;amount:string}[]; services?:{service_type:string;amount:string}[]; daily?:{day:string;collector:string;method:string;received:string;reversed:string;net:string}[]; billed:string; received:string; pending:string; overdue:string; discounts:string; legacyReported:string; historicalRecovery:string; unreconciled:number; aging:string[]; methods:{method:string;amount:string}[]; administrators:{created_by:string;collector?:string;amount:string}[]; asOf?:string; receivedToday?:string; receivedMonth?:string }
const summary=ref<Summary|null>(null);
interface CollectionSummary{zoneId:string|null;asOf:string;totalContracts:number;buckets:{bucket:string;contracts:number;amount:string}[];dueToday:{contracts:number;amount:string};inGrace:{contracts:number;amount:string};overdueNoGrace:{contracts:number;amount:string};courtesy:{contracts:number;amount:string};notConfigured:number}
const collection=ref<CollectionSummary|null>(null);
const bucketCount=(b:string)=>collection.value?.buckets.find(x=>x.bucket===b)?.contracts??0;
const canAdmin=computed(()=>['SUPERADMIN','ADMIN'].includes(auth.role??''));
const canDelete=computed(()=>auth.role==='SUPERADMIN');
const rows=computed(()=>{const q=search.value.toLowerCase();const r=store.invoices.filter(i=>(!zone.value||i.service_contracts?.zone_id===zone.value)&&(!q||`${i.invoice_number} ${i.clients?.first_name} ${i.clients?.last_name} ${i.service_contracts?.contract_number}`.toLowerCase().includes(q)));return grouped.value?[...r].sort((a,b)=>(a.service_contracts?.zones?.name??'').localeCompare(b.service_contracts?.zones?.name??'')):r;});
const displayState=(i:Invoice)=>i.status==='pending'&&penCents(i.amount_paid)>0?'Parcial':({pending:'Pendiente',paid:'Pagada',cancelled:'Anulada',exonerada:'Exonerada'}[i.status]);
const clientName=(i:Invoice)=>`${i.clients?.first_name??''} ${i.clients?.last_name??''}`;
async function load(){loading.value=true;error.value='';try{await Promise.all([store.fetchInvoices({page:page.value,from:from.value,to:to.value,status:state.value||undefined,contractId:contractId.value||undefined,search:search.value,zone:zone.value}),loadSummary()]);}catch(e){error.value=e instanceof Error?e.message:'No se pudo cargar la información';}finally{loading.value=false;}}
let summaryKey='',collectionKey:string|null=null;
function invalidateSummary(){summary.value=null;summaryKey='';collectionKey=null;}
async function loadSummary(){const key=JSON.stringify([from.value,to.value,zone.value]);if(key!==summaryKey||!summary.value){const {data,error:e}=await supabase.rpc('finance_dashboard',{p_from:from.value,p_to:to.value,p_zone:zone.value||null});if(e){summary.value=null;throw new Error('Información financiera no habilitada. La migración y conciliación siguen pendientes; no se muestran cifras de ejemplo.');}summary.value=data as Summary;summaryKey=key;}
 // Independiente del periodo elegido para el resto del resumen (es "ahora",
 // no "del rango") - solo se recarga si cambia la zona, nunca con cada clic
 // de Aplicar sobre fechas, para no repetir la misma consulta de balde.
 if(zone.value!==collectionKey){const {data,error:e}=await supabase.rpc('finance_collection_summary',{p_zone:zone.value||null});if(!e)collection.value=data as CollectionSummary;collectionKey=zone.value;}}
async function apply(){if(mode.value!=='range'){from.value=`${year.value}-${mode.value==='year'?'01':month.value}-01`;const m=mode.value==='year'?12:Number(month.value);to.value=`${year.value}-${String(m).padStart(2,'0')}-${new Date(Number(year.value),m,0).getDate()}`;}if(!from.value||!to.value||from.value>to.value){error.value='Revisa el rango de fechas.';return;}page.value=1;await load();}
onMounted(async()=>{const z=await supabase.from('zones').select('id,name').order('name');zones.value=z.data??[];await load();});
const paying=ref(false),payOpen=ref(false),review=ref(false),payQuery=ref(''),payInvoices=ref<Invoice[]>([]),selected=ref<string[]>([]),payAmount=ref(''),method=ref('cash'),reference=ref(''),reason=ref('Cobro registrado por administración'),payError=ref(''),requestId=ref(''),payContract=ref('');
const pendingSum=computed(()=>payInvoices.value.filter(i=>selected.value.includes(i.id)).reduce((s,i)=>s+penCents(i.amount_due),0));
const receivedCents=computed(()=>{try{return penCents(payAmount.value)}catch{return 0}});
const payingPeriods=computed(()=>payInvoices.value.filter(i=>selected.value.includes(i.id)));
// El importe se autocompleta con la suma de lo seleccionado (evita el error
// mas comun: marcar facturas y olvidar actualizar el monto a mano). Se deja
// de autocompletar en cuanto el administrador edita el campo a proposito
// (pago parcial o adelantado), y se reactiva al cambiar de contrato/seleccion.
const amountTouched=ref(false);
watch(selected,()=>{if(!amountTouched.value)payAmount.value=pendingSum.value?penDecimal(pendingSum.value):'';},{deep:true});
function touchAmount(){amountTouched.value=true;}
function selectAllPending(){selected.value=payInvoices.value.map(i=>i.id);amountTouched.value=false;}
async function openPayment(i?:Invoice){payOpen.value=true;review.value=false;requestId.value=crypto.randomUUID();payError.value='';reference.value='';method.value='cash';payInvoices.value=[];selected.value=[];payCandidates.value=[];payAmount.value='';amountTouched.value=false;payContract.value=i?.contract_id??'';payQuery.value=i?.service_contracts?.contract_number??'';if(i){payInvoices.value=(await store.fetchInvoicesByContract(i.contract_id)).filter(x=>x.status==='pending');selected.value=[i.id];payAmount.value=penDecimal(penCents(i.amount_due));}}
type PayCandidate={id:string;client_id:string;contract_number:string;client_code:string;customer:string;service_type:string;zone:string;reconciled:boolean};
const payCandidates=ref<PayCandidate[]>([]);
async function choosePay(c:PayCandidate){payContract.value=c.id;payInvoices.value=(await store.fetchInvoicesByContract(c.id)).filter(i=>i.status==='pending');selected.value=[];amountTouched.value=false;payAmount.value='';payCandidates.value=[];payQuery.value=c.customer+' / '+c.contract_number+' / '+c.client_code;}
async function findPay(){payError.value='';payContract.value='';payInvoices.value=[];selected.value=[];payCandidates.value=[];const q=payQuery.value.trim();if(q.length<3){payError.value='Escribe al menos tres caracteres del cliente, DNI, contrato o cintillo.';return;}const {data,error:e}=await supabase.rpc('finance_search_contracts',{p_search:q,p_zone:zone.value||null});if(e){payError.value=e.message;return;}payCandidates.value=data??[];if(!payCandidates.value.length)payError.value='No hay coincidencias para este cliente, DNI, contrato o cintillo.';}
function reviewPayment(){payError.value='';try{if(penCents(payAmount.value)<=0||!payContract.value)throw Error('Selecciona un contrato e indica el importe recibido.');if(method.value!=='cash'&&!reference.value.trim())throw Error('Registra el número de operación.');if(reason.value.trim().length<5)throw Error('Indica el motivo de la operación.');review.value=true;}catch(e){payError.value=e instanceof Error?e.message:'Pago inválido';}}
async function confirmPayment(){if(paying.value)return;paying.value=true;payError.value='';try{const result=await store.recordPayment({requestId:requestId.value,contractId:payContract.value,invoiceIds:selected.value,amount:penDecimal(penCents(payAmount.value)),method:method.value,reference:reference.value,reason:reason.value});notice.value=`Pago ${result.paymentId}: recibido ${formatPen(result.received)}, aplicado ${formatPen(result.applied)}, saldo a favor ${formatPen(result.credit)}. No se ejecutó ninguna reactivación.`;payOpen.value=false;void receiptView.value?.open(result.paymentId);await dailyView.value?.refresh();await ponCollections.value?.refresh();invalidateSummary();await load();}catch(e){payError.value=e instanceof Error?e.message:'No se pudo registrar el pago. Reintenta con esta misma operación.';}finally{paying.value=false;}}
const historyOpen=ref(false),history=ref<{openingBalances?:{kind:string;started_on:string;reason:string;result:{openingDebt?:string;openingCredit?:string}}[];payments:Record<string,unknown>[];adjustments:Record<string,unknown>[];audit:Record<string,unknown>[]}|null>(null),historyContract=ref('');
async function openHistory(i:Invoice){historyOpen.value=true;history.value=null;historyContract.value=i.service_contracts?.contract_number??i.contract_id;const {data,error:e}=await supabase.rpc('finance_history',{p_contract_id:i.contract_id});if(e){error.value='No se pudo cargar el historial financiero';return;}history.value=data;}
const editOpen=ref(false),editing=ref<Invoice|null>(null),editError=ref(''),saving=ref(false);
const form=ref({contract_id:'',client_id:'',amount:'',period_start:'',period_end:'',due_date:'',notes:''});
function openEdit(i?:Invoice){editing.value=i??null;form.value={contract_id:i?.contract_id??'',client_id:i?.client_id??'',amount:i?String(i.amount):'',period_start:i?.period_start??from.value,period_end:i?.period_end??to.value,due_date:i?.due_date??limaDate(),notes:i?.notes??''};editError.value='';editOpen.value=true;}
async function saveInvoice(){if(saving.value)return;saving.value=true;editError.value='';try{const amount=penCents(form.value.amount);if(amount<=0||form.value.notes.trim().length<5)throw Error('Importe positivo y motivo (mínimo cinco caracteres) requeridos.');const payload={...form.value,amount:Number(penDecimal(amount))};if(editing.value){await store.updateInvoice(editing.value.id,payload);}else{const {data,error:e}=await supabase.from('service_contracts').select('id,client_id').eq('contract_number',form.value.contract_id).single();if(e||!data)throw Error('Escribe el código exacto de un contrato existente.');await store.createInvoice({...payload,contract_id:data.id,client_id:data.client_id,status:'pending'});}editOpen.value=false;invalidateSummary();await load();}catch(e){editError.value=e instanceof Error?e.message:'No se pudo guardar';}finally{saving.value=false;}}
const adjustmentOpen=ref(false),adjustmentInvoice=ref<Invoice|null>(null),adjustmentId=ref(''),adjustmentAmount=ref(''),adjustmentKind=ref('averia'),adjustmentReason=ref(''),adjustmentError=ref('');
function openAdjustment(i:Invoice){adjustmentInvoice.value=i;adjustmentId.value=crypto.randomUUID();adjustmentAmount.value=String(i.amount_due);adjustmentKind.value='averia';adjustmentReason.value='';adjustmentError.value='';adjustmentOpen.value=true;}
async function saveAdjustment(){if(saving.value||!adjustmentInvoice.value)return;saving.value=true;try{await apiFetch(`/api/invoices/${adjustmentInvoice.value.id}/adjustments`,{method:'POST',body:JSON.stringify({operationId:adjustmentId.value,amount:penDecimal(penCents(adjustmentAmount.value)),kind:adjustmentKind.value,reason:adjustmentReason.value})});adjustmentOpen.value=false;invalidateSummary();await load();}catch(e){adjustmentError.value=e instanceof Error?e.message:'No se pudo aplicar';}finally{saving.value=false;}}
async function cancel(i:Invoice){const motive=window.prompt('Motivo de anulación (mínimo cinco caracteres)');if(!motive)return;if(motive.trim().length<5){error.value='Indica un motivo de al menos cinco caracteres.';return;}try{await store.updateInvoice(i.id,{status:'cancelled',notes:motive.trim()});invalidateSummary();await load();}catch(e){error.value=e instanceof Error?e.message:'No se pudo anular; revisa los movimientos de la factura.';}}
async function remove(i:Invoice){if(!canDelete.value||!window.confirm('¿Eliminar esta factura? Solo SUPERADMIN. Las facturas con pagos conservan sus referencias y no pueden borrarse.'))return;try{await store.deleteInvoice(i.id);invalidateSummary();await load();}catch(e){error.value=e instanceof Error?e.message:'No se pudo eliminar';}}
function exportCsv(){const fields=['Factura','Cliente','Contrato','Zona','Servicio','Periodo inicio','Periodo fin','Emision','Vencimiento','Importe PEN','Pagado PEN','Saldo PEN','Estado'];const data=rows.value.map(i=>[i.invoice_number,clientName(i),i.service_contracts?.contract_number,i.service_contracts?.zones?.name,i.service_contracts?.service_type,i.period_start,i.period_end,i.created_at,i.due_date,i.amount,i.amount_paid??0,i.amount_due,displayState(i)]);const safe=(v:unknown)=>'"'+String(v??'').replace(/^[=+@-]/,"'").replaceAll('"','""')+'"';const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\uFEFF'+[fields,...data].map(row=>row.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));a.download='facturas-pagina-visible.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
const asMoney=(v:unknown)=>formatPen(String(v??'0'));
const dateLabel=(v:unknown)=>new Date(String(v)).toLocaleString('es-PE',{timeZone:'America/Lima'});
</script>

<template>
 <section class="finance-workspace">
  <header class="finance-header"><div><span class="finance-eyebrow">COMERCIAL · CONTROL INTERNO</span><h1>Facturación</h1><p>Facturación emitida, dinero recibido y saldos por cobrar.</p></div><div class="finance-actions"><button class="btn-ghost" @click="openEdit()">Nueva factura</button><button class="btn-primary" @click="openPayment()">+ Registrar pago</button></div></header>
  <div class="finance-warning"><b>Información no conciliada con Excel</b><span>Los históricos no autorizan cortes. Las suspensiones y reactivaciones están bloqueadas durante esta fase.</span></div>
  <nav class="finance-tabs" aria-label="Secciones financieras"><button v-for="(label,n) in tabs" :key="label" :class="{active:tab===n}" @click="tab=n">{{ label }}</button></nav>
  <form v-if="tab!==2" class="finance-filters" @submit.prevent="apply"><label>Período<select v-model="mode"><option value="month">Mes</option><option value="year">Año</option><option value="range">Rango personalizado</option></select></label><label v-if="mode!=='range'">Año<input v-model="year" type="number" min="2020" max="2100"></label><label v-if="mode==='month'">Mes<select v-model="month"><option v-for="n in 12" :key="n" :value="String(n).padStart(2,'0')">{{ new Intl.DateTimeFormat('es-PE',{month:'long'}).format(new Date(2026,n-1,15)) }}</option></select></label><template v-if="mode==='range'"><label>Desde<input v-model="from" type="date"></label><label>Hasta<input v-model="to" type="date"></label></template><label>Zona PON<select v-model="zone"><option value="">Todas las zonas</option><option v-for="z in zones" :key="z.id" :value="z.id">{{ z.name }}</option></select></label><button class="btn-secondary" :disabled="loading">Aplicar</button><span class="finance-period">{{ from }} — {{ to }} · PEN · Perú</span></form>
  <p v-if="error" role="alert" class="finance-error">{{ error }}</p><p v-if="notice" role="status" class="finance-notice">{{ notice }}</p>
  <div v-if="tab!==2" class="finance-metrics"><article v-for="k in [{key:'billed',title:'Facturado',note:'Cargos emitidos en el período'},{key:'received',title:'Recaudado',note:'Pagos del libro, por recepción'},{key:'pending',title:'Saldo pendiente',note:'Saldo actual · facturas del período'},{key:'overdue',title:'Deuda vencida',note:'Información no conciliada'}]" :key="k.key"><span>{{ k.title }}</span><strong>{{ summary?asMoney(summary[k.key as keyof Summary]):'—' }}</strong><small>{{ k.note }}</small></article></div>
  <template v-if="tab===0">
   <div class="finance-metrics finance-metrics-today"><article><span>Recaudado hoy</span><strong>{{ summary?asMoney(summary.receivedToday):'—' }}</strong><small>{{ summary?.asOf?`Al ${summary.asOf}`:'Dinero recibido hoy (America/Lima)' }}</small></article><article><span>Recaudado del mes</span><strong>{{ summary?asMoney(summary.receivedMonth):'—' }}</strong><small>Del 1.° del mes a hoy, sin importar el período filtrado arriba</small></article><article :class="{'finance-metric-warn':bucketCount('vence_hoy')>0}"><span>Por cobrar hoy</span><strong>{{ collection?asMoney(collection.dueToday.amount):'—' }}</strong><small>{{ collection?`${collection.dueToday.contracts} contrato(s) con ciclo confirmado que vence hoy`:'Cargando…' }}</small></article><article :class="{'finance-metric-warn':bucketCount('en_prorroga')>0}"><span>En prórroga</span><strong>{{ collection?asMoney(collection.inGrace.amount):'—' }}</strong><small>{{ collection?`${collection.inGrace.contracts} contrato(s) de pago adelantado, dentro de los días de gracia`:'Cargando…' }}</small></article><article :class="{'finance-metric-danger':bucketCount('vencido_sin_prorroga')>0}"><span>Vencido sin prórroga</span><strong>{{ collection?asMoney(collection.overdueNoGrace.amount):'—' }}</strong><small>{{ collection?`${collection.overdueNoGrace.contracts} contrato(s) elegibles para gestión de cobranza`:'Cargando…' }}</small></article></div>
   <p v-if="collection" class="finance-help">{{ collection.notConfigured }} contrato(s) sin modalidad/día de cobranza confirmado — no cuentan como al día ni como vencidos; falta configurarlos en Cobranzas → Confirmar condiciones. {{ collection.courtesy.contracts }} contrato(s) de cortesía (servicio gratuito confirmado, {{ asMoney(collection.courtesy.amount) }} de mensualidad de lista) — excluidos de deuda, morosidad, ingresos proyectados y elegibilidad para corte. Proyección sobre la mensualidad vigente de cada contrato, no sobre saldo facturado real.</p>
   <FinanceCharts v-if="summary" :summary="summary"/><div class="finance-grid"><article class="finance-panel"><h2>Lectura financiera del período</h2><p>Cobranza de períodos anteriores: <b>{{ summary?formatPen(summary.historicalRecovery):'—' }}</b></p><p>Descuentos y exoneraciones: <b>{{ summary?formatPen(summary.discounts):'—' }}</b></p><p>Pagos históricos reportados: <b>{{ summary?formatPen(summary.legacyReported):'—' }}</b> · separados del libro nuevo.</p><div class="finance-rule">Una factura emitida no es un ingreso de caja. Los descuentos reducen deuda, sin registrar dinero recibido.</div></article><article class="finance-panel"><h2>Inicio financiero seguro</h2><p v-if="summary?.openingBalance">Saldo inicial conciliado pendiente: <b>{{formatPen(summary.openingBalance)}}</b>. No es nueva facturación emitida.</p><ol><li>Revisar muestra real de Excel.</li><li>Conciliar cada cliente y contrato.</li><li>Aprobar saldos iniciales y fecha de inicio.</li><li>Habilitar una cohorte controlada.</li></ol><p>No hay importación ni habilitación masiva desde esta pantalla.</p></article></div><article class="finance-panel"><h2>Flujo de trabajo</h2><div class="finance-shortcuts"><button @click="tab=1">Revisar facturas →</button><button @click="tab=2">Consultar cobranzas →</button><button @click="router.push('/cortes')">Cortes por deuda →</button></div></article></template>
  <template v-else-if="tab===1||tab===4||tab===6">
   <div class="finance-table-tools"><input v-model="search" placeholder="Cliente, contrato o factura · página visible" aria-label="Buscar en página"><button class="btn-secondary" @click="page=1;load()">Buscar</button><select v-model="state" aria-label="Estado" @change="page=1;load()"><option value="">Todos los estados</option><option value="pending">Pendientes y parciales</option><option value="paid">Pagadas</option><option value="exonerada">Exoneradas</option><option value="cancelled">Anuladas</option></select><label><input v-model="grouped" type="checkbox"> Agrupar por zona</label><button class="btn-ghost" @click="exportCsv">Exportar página a Excel (CSV)</button></div>
   <p v-if="tab===4" class="finance-help">Selecciona Ajuste para un descuento o exoneración con motivo. No representa efectivo recibido.</p><p v-if="tab===6" class="finance-help">Abre Historial para consultar pagos, ajustes y auditoría por contrato. No se puede editar el historial.</p>
   <div class="finance-table"><table><thead><tr><th>Factura</th><th>Cliente / contrato</th><th>Zona / servicio</th><th>Período</th><th>Emisión / vence</th><th>Importe</th><th>Pagado</th><th>Saldo</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><template v-for="(i,n) in rows" :key="i.id"><tr v-if="grouped&&(n===0||rows[n-1].service_contracts?.zone_id!==i.service_contracts?.zone_id)" class="finance-group"><td colspan="10">{{ i.service_contracts?.zones?.name??'Sin zona' }}</td></tr><tr><td>{{ i.invoice_number }}<small v-if="!i.finance_reconciled">No conciliada</small></td><td><button class="finance-link" @click="router.push(`/clientes/${i.client_id}`)">{{ clientName(i) }}</button><small><button class="finance-link" @click="router.push(`/clientes/${i.client_id}/servicios/${i.contract_id}`)">{{ i.service_contracts?.contract_number }}</button></small></td><td>{{ i.service_contracts?.zones?.name??'Sin zona' }}<small>{{ i.service_contracts?.plans?.name??i.service_contracts?.service_type }}</small></td><td>{{ i.period_start }}<small>{{ i.period_end }}</small></td><td>{{ limaDate(new Date(i.created_at)) }}<small>{{ i.due_date }}</small></td><td class="finance-number">{{ formatPen(i.amount) }}</td><td class="finance-number">{{ formatPen(i.amount_paid) }}</td><td class="finance-number">{{ formatPen(i.amount_due) }}</td><td><span class="finance-badge" :class="{settled:i.status==='paid'}">{{ displayState(i) }}</span></td><td><div class="finance-row-actions"><button v-if="i.status==='pending'" class="finance-link" @click="openPayment(i)">Cobrar</button><button class="finance-link" @click="openHistory(i)">Historial</button><button v-if="canAdmin" class="finance-link" @click="openEdit(i)">Editar</button><button v-if="canAdmin&&i.status==='pending'" class="finance-link" @click="openAdjustment(i)">Ajuste</button><button v-if="i.status==='pending'&&!i.amount_paid" class="finance-link" @click="cancel(i)">Anular</button><button v-if="canDelete" class="finance-link danger" @click="remove(i)">Eliminar</button></div></td></tr></template><tr v-if="!rows.length"><td colspan="10" class="finance-empty">{{ loading?'Cargando información…':'Sin facturas para estos filtros.' }}</td></tr></tbody></table></div><div class="finance-pagination"><span>{{ store.total }} facturas · página {{ page }} · 25 por página</span><button :disabled="page===1||loading" @click="page--;load()">Anterior</button><button :disabled="page*25>=store.total||loading" @click="page++;load()">Siguiente</button></div>
  </template>
  <template v-else-if="tab===2"><div class="finance-shortcuts finance-subtabs"><button :aria-pressed="collectionsView==='pon'" @click="collectionsView='pon'">Cobranza por PON</button><button :aria-pressed="collectionsView==='daily'" @click="collectionsView='daily'">Resumen diario y anticipos</button><button v-if="canAdmin" :aria-pressed="collectionsView==='reconciliation'" @click="collectionsView='reconciliation'">Conciliar Excel</button></div><FinanceReconciliation v-if="collectionsView==='reconciliation'&&canAdmin" :zones="zones" @changed="invalidateSummary();load()"/><PonCollections v-else-if="collectionsView==='pon'" ref="ponCollections" :zones="zones" @receipt="id=>receiptView?.open(id)" @pay="openPayment" @changed="invalidateSummary();load()"/><DailyCollections v-else ref="dailyView" :zones="zones" @receipt="id=>receiptView?.open(id)"/></template>
  <template v-else-if="tab===3"><article class="finance-panel"><h2>Antigüedad de deuda</h2><p>Saldo actual de facturas emitidas en el período. Antigüedad a la fecha actual de Perú: {{ limaDate() }}. No acredita deuda real hasta conciliar.</p><div v-for="(label,n) in ['1–30 días','31–60 días','61–90 días','Más de 90 días']" :key="label" class="finance-aging"><span>{{ label }}</span><div><i :style="{width:summary&&penCents(summary.pending)>0?`${Math.min(100,penCents(summary.aging[n])/penCents(summary.pending)*100)}%`:'0%'}"></i></div><b>{{ summary?formatPen(summary.aging[n]):'—' }}</b></div></article></template>
  <template v-else-if="tab===5"><FinanceCharts v-if="summary" :summary="summary"/><article class="finance-panel"><h2>Reportes del período</h2><p>Facturado por fecha de emisión, recaudado por recepción y recuperación histórica se calculan separadamente en el servidor.</p><div class="finance-shortcuts"><button @click="tab=1">Exportar facturas →</button><button @click="tab=2">Medios y administradores →</button><button @click="tab=3">Antigüedad de deuda →</button></div><p>MRR, ARPU y evolución histórica conciliada requieren reglas comerciales y saldos iniciales aprobados. No se muestran cifras inventadas.</p></article></template>
  <p class="finance-footnote">Control interno en PEN · America/Lima · No es facturación electrónica SUNAT.</p>
 </section>
 <PaymentReceipt ref="receiptView"/>
 <Teleport to="body">
  <div v-if="payOpen" class="modal-overlay"><section class="modal-panel finance-dialog" role="dialog" aria-modal="true" aria-labelledby="payment-title"><div class="finance-dialog-head"><h2 id="payment-title">{{ review?'Confirmar pago':'Registrar pago' }}</h2><button :disabled="paying" aria-label="Cerrar pago" @click="payOpen=false">×</button></div><p class="finance-help">Pagos parciales, completos o adelantados · sin reactivación automática.</p><template v-if="!review"><div class="finance-search-pay"><label>Cliente, DNI, contrato o cintillo<input v-model="payQuery" aria-label="Buscar cliente DNI contrato cintillo" placeholder="Nombre, DNI, CTR o cintillo" @keydown.enter.prevent="findPay"></label><button class="btn-secondary" @click="findPay">Buscar</button></div><div v-if="payCandidates.length" class="finance-invoice-options finance-pay-candidates"><label v-for="c in payCandidates" :key="c.id"><span>{{c.customer}}<small>{{c.contract_number}} / {{c.client_code}} / {{c.zone}} / {{c.service_type}}</small><small v-if="!c.reconciled">Pendiente de conciliación: cobro bloqueado.</small></span><button class="finance-link" :disabled="!c.reconciled" @click="choosePay(c)">Seleccionar contrato</button><button class="finance-link" @click="router.push('/clientes/'+c.client_id)">Ficha del cliente</button></label></div><div v-if="payInvoices.length" class="finance-pay-quickpick"><button type="button" class="btn-ghost" @click="selectAllPending">Marcar todo lo pendiente ({{ payInvoices.length }})</button><button v-if="selected.length" type="button" class="btn-ghost" @click="selected=[];amountTouched=false;payAmount=''">Quitar selección</button></div><div class="finance-invoice-options"><label v-for="i in payInvoices" :key="i.id"><input v-model="selected" type="checkbox" :value="i.id"><span>{{ i.invoice_number }} · {{ i.period_start }}<small>{{ clientName(i) }} · {{ i.finance_reconciled?'Conciliada':'No conciliada' }}</small></span><b>{{ formatPen(i.amount_due) }}</b></label><p v-if="!payInvoices.length">Selecciona un contrato. Sin facturas seleccionadas, el dinero se registra como anticipo.</p></div><p v-if="payingPeriods.length" class="finance-help finance-paying-periods">Se está pagando: <b>{{ payingPeriods.map(i=>`${i.invoice_number} (${i.period_start})`).join(' · ') }}</b> — saldo de lo marcado {{ formatPen(penDecimal(pendingSum)) }}</p><div class="finance-form-grid"><label>Importe recibido (PEN)<input v-model="payAmount" inputmode="decimal" placeholder="0.00" @input="touchAmount"></label><label>Método<select v-model="method"><option value="cash">Efectivo</option><option value="yape">Yape</option><option value="plin">Plin</option><option value="transfer">Transferencia</option><option value="other">Otros</option></select></label><label>Número de operación<input v-model="reference" maxlength="100" placeholder="Requerido para medios digitales"></label><label>Motivo<input v-model="reason" maxlength="500"></label></div><p v-if="payAmount&&receivedCents!==pendingSum" class="finance-help">{{ receivedCents>pendingSum?'El excedente queda como saldo a favor del cliente (adelanto).':'Importe menor al saldo marcado: se registrará como pago parcial.' }}</p></template><div class="finance-payment-preview"><span>A aplicar <b>{{ formatPen(penDecimal(Math.min(pendingSum,receivedCents))) }}</b></span><span>Saldo restante <b>{{ formatPen(penDecimal(Math.max(0,pendingSum-receivedCents))) }}</b></span><span>Saldo a favor nuevo <b>{{ formatPen(penDecimal(Math.max(0,receivedCents-pendingSum))) }}</b></span></div><p v-if="review" class="finance-help">{{ payQuery }} · {{ formatPen(payAmount) }} · {{ method }} · {{ reference||'Sin referencia de efectivo' }}. El servidor verifica de nuevo saldo, rol y conciliación al confirmar.</p><p v-if="payError" class="finance-error" role="alert">{{ payError }}</p><div class="finance-dialog-actions"><button v-if="review" class="btn-ghost" :disabled="paying" @click="review=false">Volver</button><button v-if="!review" class="btn-primary" @click="reviewPayment">Revisar pago</button><button v-else class="btn-primary" :disabled="paying" @click="confirmPayment">{{ paying?'Registrando…':'Confirmar pago' }}</button></div></section></div>
  <div v-if="historyOpen" class="modal-overlay"><section class="modal-panel finance-dialog" role="dialog" aria-modal="true"><div class="finance-dialog-head"><h2>Historial · {{ historyContract }}</h2><button aria-label="Cerrar historial" @click="historyOpen=false">×</button></div><p v-if="!history">Cargando historial…</p><template v-else><h3>Pagos recibidos</h3><p v-for="p in history.payments" :key="String(p.id)" class="finance-history-line">{{ p.received_date_only?new Date(String(p.received_at)).toLocaleDateString('es-PE',{timeZone:'America/Lima'}):dateLabel(p.received_at) }} · {{ asMoney(p.amount) }} · {{ p.method }} · {{ p.reference||'Efectivo' }}<small>Responsable {{ p.collector??p.created_by }} · <button class="finance-link" @click="receiptView?.open(String(p.id))">Ver / descargar recibo</button> / {{ p.reason }} / {{ p.reversed_at?'REVERSADO':'Vigente' }} / Saldo adelantado {{ asMoney(p.credit_remaining) }}</small></p><p v-if="!history.payments.length">Sin pagos del nuevo libro.</p><h3>Ajustes y exoneraciones</h3><p v-for="a in history.adjustments" :key="String(a.id)">{{ a.tipo }} · {{ asMoney(a.monto) }} · {{ a.descripcion }} / {{ a.reversed_at?'Revertido':'Vigente' }}</p><template v-if="history.openingBalances?.length"><h3>Saldos iniciales conciliados</h3><p v-for="(b,n) in history.openingBalances" :key="n">{{b.started_on}} / {{b.kind==='opening_credit'?'Saldo a favor inicial':'Deuda inicial'}} / {{asMoney(b.result.openingCredit??b.result.openingDebt)}}<small>{{b.reason}} / No es efectivo recibido en el período.</small></p></template><h3>Auditoría</h3><p v-for="a in history.audit" :key="String(a.id)" class="finance-history-line">{{ dateLabel(a.created_at) }} · {{ a.accion }}<small>{{ a.actor_id }} · {{ a.motivo }}</small></p><p class="finance-help">Se muestran hasta 100 registros por categoría. Historial de solo lectura.</p></template></section></div>
  <div v-if="editOpen" class="modal-overlay"><form class="modal-panel finance-dialog" @submit.prevent="saveInvoice"><div class="finance-dialog-head"><h2>{{ editing?'Editar factura':'Nueva factura' }}</h2><button type="button" aria-label="Cerrar edición" @click="editOpen=false">×</button></div><p>La edición conserva los pagos registrados. Las correcciones monetarias requieren un ajuste auditado.</p><div class="finance-form-grid"><label>Contrato (código exacto)<input v-if="!editing" v-model="form.contract_id" required><input v-else :value="editing.service_contracts?.contract_number" disabled></label><label>Importe original PEN<input v-model="form.amount" inputmode="decimal" required></label><label>Inicio<input v-model="form.period_start" type="date" required></label><label>Fin<input v-model="form.period_end" type="date" required></label><label>Vencimiento<input v-model="form.due_date" type="date" required></label><label>Motivo / nota<input v-model="form.notes" required minlength="5"></label></div><p v-if="editError" class="finance-error">{{ editError }}</p><div class="finance-dialog-actions"><button class="btn-primary" :disabled="saving">Guardar</button></div></form></div>
  <div v-if="adjustmentOpen" class="modal-overlay"><form class="modal-panel finance-dialog" @submit.prevent="saveAdjustment"><div class="finance-dialog-head"><h2>Descuento o exoneración</h2><button type="button" aria-label="Cerrar ajuste" @click="adjustmentOpen=false">×</button></div><p>{{ adjustmentInvoice?.invoice_number }} · no registra dinero recibido.</p><div class="finance-form-grid"><label>Tipo<select v-model="adjustmentKind"><option value="averia">Descuento / compensación</option><option value="exoneracion">Exonerar saldo restante</option></select></label><label>Importe PEN<input v-model="adjustmentAmount" inputmode="decimal" required></label><label>Motivo<input v-model="adjustmentReason" required minlength="5" maxlength="500"></label></div><p v-if="adjustmentError" class="finance-error">{{ adjustmentError }}</p><div class="finance-dialog-actions"><button class="btn-primary" :disabled="saving">Confirmar ajuste auditado</button></div></form></div>
 </Teleport>
</template>
